#!/usr/bin/env bash
#
# sync-release-assets.sh reconciles the assets of one existing GitHub Release
# to the exact set described by a manifest generated by
# generate-release-manifest.sh.
#
# Behavior:
#   - Only the release pointed to by --tag is touched, other releases and the
#     release metadata itself are never modified.
#   - Every manifest record is verified against the local file (existence and
#     SHA-256) before any API call is made. A single failure aborts the run and
#     leaves the release unchanged.
#   - Assets uploaded by this script are marked with the label
#     "gogs-managed:sha256=<digest>". This label is the ownership marker:
#     managed assets that disappear from the manifest are deleted, while assets
#     without it (e.g. uploaded manually from the web UI) are never modified.
#   - The script is a pure reconciliation loop. Uploading, deleting and
#     replacing are each idempotent, so interrupting a run and starting it again
#     converges to the manifest state without duplicate assets.
#
# Usage:
#   sync-release-assets.sh --repo OWNER/REPO --tag TAG \
#       --manifest MANIFEST.json --assets-dir DIR [--dry-run]

set -euo pipefail

LABEL_PREFIX='gogs-managed:sha256:'

usage() {
	sed -n '2,23p' "$0" | sed 's/^# \{0,1\}//'
	exit 1
}

log() {
	echo "sync-release-assets: $*"
}

fail() {
	echo "sync-release-assets: error: $*" >&2
	exit 1
}

repo=""
tag=""
manifest_path=""
assets_dir=""
dry_run=false

while [ "$#" -gt 0 ]; do
	case "$1" in
		--repo)
			[ "$#" -ge 2 ] || fail "missing value for --repo"
			repo=$2
			shift 2
			;;
		--tag)
			[ "$#" -ge 2 ] || fail "missing value for --tag"
			tag=$2
			shift 2
			;;
		--manifest)
			[ "$#" -ge 2 ] || fail "missing value for --manifest"
			manifest_path=$2
			shift 2
			;;
		--assets-dir)
			[ "$#" -ge 2 ] || fail "missing value for --assets-dir"
			assets_dir=$2
			shift 2
			;;
		--dry-run)
			dry_run=true
			shift
			;;
		-h|--help)
			usage
			;;
		*)
			fail "unknown argument: $1"
			;;
	esac
done

[ -n "$repo" ] || fail "--repo is required"
[ -n "$tag" ] || fail "--tag is required"
[ -n "$manifest_path" ] || fail "--manifest is required"
[ -n "$assets_dir" ] || fail "--assets-dir is required"
[ -f "$manifest_path" ] || fail "manifest does not exist: $manifest_path"
[ -d "$assets_dir" ] || fail "assets directory does not exist: $assets_dir"

command -v jq >/dev/null 2>&1 || fail "jq is required"
command -v gh >/dev/null 2>&1 || fail "gh is required"

if command -v sha256sum >/dev/null 2>&1; then
	file_sha() {
		sha256sum "$1" | awk '{print $1}'
	}
elif command -v shasum >/dev/null 2>&1; then
	file_sha() {
		shasum -a 256 "$1" | awk '{print $1}'
	}
else
	fail "neither sha256sum nor shasum is available"
fi

file_size() {
	wc -c < "$1" | tr -d '[:space:]'
}

uri_encode() {
	jq -rn --arg value "$1" '$value | @uri'
}

is_managed_label() {
	[[ "$1" =~ ^gogs-managed:sha256:[0-9a-f]{64}$ ]]
}

work_dir=$(mktemp -d)
trap 'rm -rf "$work_dir"' EXIT

failures_file=$work_dir/verification-failures
: > "$failures_file"

# Phase 1: validate the manifest and verify every local file before touching
# the network with a write request, so a bad record voids the whole sync.
jq -e '
	type == "object"
	and (.version == 1)
	and (.assets | type == "array")
' "$manifest_path" >/dev/null || fail "manifest must be an object with \"version\": 1 and an \"assets\" array"

jq -e '.assets | (map(.name) | length == (unique | length))' "$manifest_path" >/dev/null \
	|| fail "manifest contains duplicate asset names"

invalid_entries=$(jq -r '
	.assets
	| to_entries
	| map(
		select(
			(.value | type != "object")
			or (
				(.value.name | type != "string")
				or (.value.name == "")
				or (.value.sha256 | type != "string")
				or (.value.name | test("^[^/\\\\]+$") | not)
				or (.value.name == "." or .value.name == "..")
				or (.value.name | explode | any(. < 32))
			)
		)
		| "invalid manifest entry at index \(.key): \(.value | tojson)"
	)
	| .[]
' "$manifest_path")
if [ -n "$invalid_entries" ]; then
	log "verification failed, no changes were made:"
	printf '%s\n' "$invalid_entries" | sed 's/^/  - /' >&2
	exit 1
fi

desired_file=$work_dir/desired.json
: > "$desired_file"

entry_count=0
while IFS= read -r entry; do
	name=$(jq -r '.name' <<< "$entry")
	digest=$(jq -r '.sha256' <<< "$entry")

	if ! [[ "$digest" =~ ^[0-9a-f]{64}$ ]]; then
		echo "$name: sha256 must be 64 lowercase hexadecimal characters, got \"$digest\"" >> "$failures_file"
		continue
	fi

	file_path=$assets_dir/$name
	if [ ! -f "$file_path" ]; then
		echo "$name: file not found in assets directory: $file_path" >> "$failures_file"
		continue
	fi

	actual_digest=$(file_sha "$file_path")
	if [ "$actual_digest" != "$digest" ]; then
		echo "$name: checksum mismatch (manifest: $digest, actual: $actual_digest)" >> "$failures_file"
		continue
	fi

	jq -n --arg name "$name" --arg sha256 "$digest" --arg size "$(file_size "$file_path")" \
		'{name: $name, sha256: $sha256, size: ($size | tonumber)}' >> "$desired_file"
	entry_count=$((entry_count + 1))
done < <(jq -c '.assets[]' "$manifest_path")

if [ -s "$failures_file" ]; then
	log "verification failed, no changes were made:"
	sed 's/^/  - /' "$failures_file" >&2
	exit 1
fi

jq -s '.' "$desired_file" > "$desired_file.array"
mv "$desired_file.array" "$desired_file"

log "verified $entry_count manifest record(s) against local files"

# Phase 2: resolve the single release targeted by --tag.
tag_encoded=$(uri_encode "$tag")
release_json=$(gh api -H "Accept: application/vnd.github+json" \
	"repos/$repo/releases/tags/$tag_encoded" 2>/dev/null) \
	|| fail "release does not exist or is not accessible: $repo ($tag); this script only syncs to an existing release"

release_id=$(jq -r '.id' <<< "$release_json")
log "syncing release $repo ($tag, id $release_id)"

remote_asset_count() { # $1 = asset name
	jq --arg name "$1" '[.assets[] | select(.name == $name)] | length' <<< "$release_json"
}

remote_asset() { # $1 = asset name, prints the asset JSON
	jq -c --arg name "$1" '.assets[] | select(.name == $name) | {id, name, label: (.label // ""), size}' <<< "$release_json"
}

desired_has_name() { # $1 = asset name
	jq -e --arg name "$1" 'any(.name == $name)' "$desired_file" >/dev/null
}

# Phase 3: compute the reconciliation plan.
uploads_file=$work_dir/uploads
replaces_file=$work_dir/replaces
deletes_file=$work_dir/deletes
conflicts_file=$work_dir/conflicts
untouched_file=$work_dir/untouched
: > "$uploads_file"
: > "$replaces_file"
: > "$deletes_file"
: > "$conflicts_file"
: > "$untouched_file"

while IFS=$'\t' read -r name digest size; do
	count=$(remote_asset_count "$name")
	if [ "$count" -eq 0 ]; then
		printf '%s\n' "$name" >> "$uploads_file"
		continue
	fi
	if [ "$count" -gt 1 ]; then
		fail "release contains $count assets named \"$name\", GitHub should guarantee unique names"
	fi

	asset=$(remote_asset "$name")
	asset_id=$(jq -r '.id' <<< "$asset")
	asset_label=$(jq -r '.label' <<< "$asset")
	asset_size=$(jq -r '.size' <<< "$asset")

	if ! is_managed_label "$asset_label"; then
		printf '%s\n' "$name" >> "$conflicts_file"
		continue
	fi

	remote_digest=${asset_label#"$LABEL_PREFIX"}
	if [ "$remote_digest" = "$digest" ] && [ "$asset_size" = "$size" ]; then
		:
	else
		printf '%s\t%s\n' "$asset_id" "$name" >> "$replaces_file"
	fi
done < <(jq -r '.[] | [.name, .sha256, (.size | tostring)] | @tsv' "$desired_file")

while IFS=$'\t' read -r asset_id asset_name asset_label; do
	if is_managed_label "$asset_label"; then
		if ! desired_has_name "$asset_name"; then
			printf '%s\t%s\n' "$asset_id" "$asset_name" >> "$deletes_file"
		fi
	else
		printf '%s\n' "$asset_name" >> "$untouched_file"
	fi
done < <(jq -r '.assets[] | [(.id | tostring), .name, (.label // "")] | @tsv' <<< "$release_json")

if [ -s "$conflicts_file" ]; then
	log "conflicting assets uploaded outside of this manifest were found and no changes were made:"
	sed 's/^/  - /' "$conflicts_file"
	fail "delete or rename the conflicting assets manually, or remove them from the manifest"
fi

log "plan: $(wc -l < "$uploads_file" | tr -d '[:space:]') to upload, $(wc -l < "$replaces_file" | tr -d '[:space:]') to replace, $(wc -l < "$deletes_file" | tr -d '[:space:]') to delete"
if [ -s "$untouched_file" ]; then
	log "leaving unmanaged asset(s) untouched:"
	sed 's/^/  - /' "$untouched_file"
fi

if "$dry_run"; then
	log "dry run, no changes were made"
	exit 0
fi

# Phase 4: apply the plan. Each step is independently idempotent, so a crash
# leaves a state that the next run reconciles.
require_managed() { # $1 = asset id
	local asset_id=$1
	local label
	label=$(gh api -H "Accept: application/vnd.github+json" \
		"repos/$repo/releases/assets/$asset_id" --jq '.label // ""')
	is_managed_label "$label" || fail "asset $asset_id is no longer marked as managed, aborting to protect a possibly manual upload"
}

delete_asset() { # $1 = asset id, $2 = asset name
	local asset_id=$1 asset_name=$2
	require_managed "$asset_id"
	gh api --method DELETE -H "Accept: application/vnd.github+json" \
		"repos/$repo/releases/assets/$asset_id" >/dev/null
	log "deleted stale asset: $asset_name ($asset_id)"
}

upload_asset() { # $1 = asset name
	local name=$1
	local digest file_path encoded_name encoded_label
	digest=$(jq -r --arg name "$1" '.[] | select(.name == $name) | .sha256' "$desired_file")
	file_path=$assets_dir/$name
	encoded_name=$(uri_encode "$name")
	encoded_label=$(uri_encode "${LABEL_PREFIX}${digest}")

	if gh api --method POST \
		-H "Accept: application/vnd.github+json" \
		-H "Content-Type: application/octet-stream" \
		"https://uploads.github.com/repos/$repo/releases/$release_id/assets?name=${encoded_name}&label=${encoded_label}" \
		--input "$file_path" >/dev/null; then
		log "uploaded asset: $name"
		return 0
	fi

	# A failed upload can be caused by a concurrent run that created the same
	# asset name. Take over the slot only when it is marked as managed.
	log "upload of $name failed, checking for a concurrent upload"
	local existing existing_label
	existing=$(gh api -H "Accept: application/vnd.github+json" \
		"repos/$repo/releases/tags/$tag_encoded" \
		| jq -c --arg name "$name" '.assets[] | select(.name == $name) | {id, label: (.label // "")}')
	if [ -z "$existing" ]; then
		fail "failed to upload asset: $name"
	fi
	existing_label=$(jq -r '.label' <<< "$existing")
	if ! is_managed_label "$existing_label"; then
		fail "asset name $name is occupied by an unmanaged asset, aborting"
	fi
	local existing_id
	existing_id=$(jq -r '.id' <<< "$existing")
	log "removing concurrent managed upload $existing_id and retrying"
	delete_asset "$existing_id" "$name"
	gh api --method POST \
		-H "Accept: application/vnd.github+json" \
		-H "Content-Type: application/octet-stream" \
		"https://uploads.github.com/repos/$repo/releases/$release_id/assets?name=${encoded_name}&label=${encoded_label}" \
		--input "$file_path" >/dev/null
	log "uploaded asset: $name"
}

while IFS=$'\t' read -r asset_id name; do
	delete_asset "$asset_id" "$name"
	upload_asset "$name"
done < "$replaces_file"

while IFS= read -r name; do
	upload_asset "$name"
done < "$uploads_file"

while IFS=$'\t' read -r asset_id name; do
	delete_asset "$asset_id" "$name"
done < "$deletes_file"

# Phase 5: re-read the release and assert that it matches the manifest.
final_json=$(gh api -H "Accept: application/vnd.github+json" \
	"repos/$repo/releases/tags/$tag_encoded")

final_failures=$work_dir/final-failures
: > "$final_failures"

while IFS=$'\t' read -r name digest size; do
	final_asset=$(jq -c --arg name "$name" '[.assets[] | select(.name == $name)]' <<< "$final_json")
	final_count=$(jq 'length' <<< "$final_asset")
	if [ "$final_count" -ne 1 ]; then
		echo "$name: expected 1 asset after sync, found $final_count" >> "$final_failures"
		continue
	fi
	final_label=$(jq -r '.[0].label // ""' <<< "$final_asset")
	final_size=$(jq -r '.[0].size' <<< "$final_asset")
	if ! is_managed_label "$final_label"; then
		echo "$name: asset is missing the managed label" >> "$final_failures"
	elif [ "${final_label#"$LABEL_PREFIX"}" != "$digest" ] || [ "$final_size" != "$size" ]; then
		echo "$name: asset content does not match manifest after sync" >> "$final_failures"
	fi
done < <(jq -r '.[] | [.name, .sha256, (.size | tostring)] | @tsv' "$desired_file")

managed_count=$(jq '[.assets[] | select((.label // "") | test("^gogs-managed:sha256:[0-9a-f]{64}$"))] | length' <<< "$final_json")
if [ "$managed_count" -ne "$entry_count" ]; then
	echo "managed asset count is $managed_count after sync, expected $entry_count" >> "$final_failures"
fi

if [ -s "$final_failures" ]; then
	log "post-sync verification failed, rerun to converge:"
	sed 's/^/  - /' "$final_failures" >&2
	exit 1
fi

log "release $repo ($tag) is in sync with $manifest_path ($entry_count asset(s))"
